const PLATFORMS = ['telegram', 'vk'];

function escapeHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeAttr(s) {
  return escapeHtml(s).replace(/"/g, '&quot;');
}

// Ссылка на источник обязательна: без неё или с нечитаемой ссылкой пост не собирается.
function sourceUrl(link) {
  let u;
  try {
    u = new URL(String(link || '').trim());
  } catch {
    throw new Error('нет ссылки на источник');
  }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new Error('ссылка на источник не http(s)');
  return u;
}

// Обрезает текст до limit знаков: по концу предложения, если он не слишком
// далеко, иначе по пробелу, и ставит многоточие. Суррогатные пары не рвёт.
function truncate(text, limit) {
  const s = String(text ?? '').trim();
  if (s.length <= limit) return s;
  if (limit <= 1) return '…'.slice(0, Math.max(0, limit));
  let cut = s.slice(0, limit - 1);
  if (/[\uD800-\uDBFF]$/.test(cut)) cut = cut.slice(0, -1);
  const sentence = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (sentence >= cut.length * 0.6) return cut.slice(0, sentence + 1);
  const space = cut.lastIndexOf(' ');
  if (space >= cut.length * 0.6) cut = cut.slice(0, space);
  return cut.replace(/[\s,;:.\-]+$/, '') + '…';
}

// Собирает пост: заголовок жирным, текст, ссылка на источник отдельной строкой.
// Длина считается по видимому тексту (без тегов, сущности как один знак).
// options.caption: true, если пост идёт подписью к картинке (лимит 1024).
function buildPost({ title, text, link, sourceName } = {}, options = {}) {
  const url = sourceUrl(link);
  const limit = options.limit ?? (options.caption ? TELEGRAM_CAPTION_LIMIT : TELEGRAM_TEXT_LIMIT);
  const name = String(sourceName || '').trim() || url.hostname.replace(/^www\./, '');
  const head = String(title || '').trim();
  const body = String(text || '').trim();
  if (!body) throw new Error('пустой текст поста');

  const sourceLine = `Источник: ${name}`;
  const fixed = (head ? head.length + 2 : 0) + 2 + sourceLine.length;
  const room = limit - fixed;
  if (room < 20) throw new Error('не хватает места для текста поста');
  const visibleBody = truncate(body, room);

  const html =
    (head ? `<b>${escapeHtml(head)}</b>\n\n` : '') +
    `${escapeHtml(visibleBody)}\n\n` +
    `Источник: <a href="${escapeAttr(url.href)}">${escapeHtml(name)}</a>`;
  const visibleLength = (head ? head.length + 2 : 0) + visibleBody.length + 2 + sourceLine.length;
  return { text: html, parse_mode: 'HTML', visibleLength, truncated: visibleBody !== body };
}

// Пост для ВКонтакте: простой текст без HTML. Заголовок первой строкой,
// затем текст и подпись источника, ссылка последней отдельной строкой
// (ВКонтакте сам делает её кликабельной). Длина считается по всему тексту.
function buildVkPost({ title, text, link, sourceName } = {}, options = {}) {
  const url = sourceUrl(link);
  const limit = options.limit ?? VK_TEXT_LIMIT;
  const name = String(sourceName || '').trim() || url.hostname.replace(/^www\./, '');
  const head = String(title || '').replace(/\s+/g, ' ').trim();
  const body = String(text || '').replace(/\r\n?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (!body) throw new Error('пустой текст поста');

  const tail = `Источник: ${name}\n${url.href}`;
  const fixed = (head ? head.length + 2 : 0) + 2 + tail.length;
  const room = limit - fixed;
  if (room < 20) throw new Error('не хватает места для текста поста');
  const visibleBody = truncate(body, room);

  const out = (head ? `${head}\n\n` : '') + `${visibleBody}\n\n${tail}`;
  return { text: out, visibleLength: out.length, truncated: visibleBody !== body };
}

// Площадка из поля PLATFORM узла «Настройки»; пусто значит telegram.
function platformOf(settings = {}) {
  const p = String((settings && settings.PLATFORM) ?? '').trim().toLowerCase() || 'telegram';
  if (!PLATFORMS.includes(p)) throw new Error(`неизвестная площадка: ${p}`);
  return p;
}

// Сборка поста для выбранной площадки.
function buildPostFor(platform, fields, options = {}) {
  if (platform === 'vk') return buildVkPost(fields, options);
  if (platform === 'telegram') return buildPost(fields, options);
  throw new Error(`неизвестная площадка: ${platform}`);
}

// Подставляет поля новости в шаблон промпта: {{title}}, {{description}}, {{link}}, {{maxLength}}.
// Неизвестная подстановка остаётся видимой, чтобы ошибку в шаблоне было легко заметить.
function fillPrompt(template, vars = {}) {
  return String(template).replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) =>
    Object.prototype.hasOwnProperty.call(vars, k) ? String(vars[k] ?? '') : m
  );
}

if (typeof module !== 'undefined') {
  module.exports = {
    TELEGRAM_TEXT_LIMIT,
    TELEGRAM_CAPTION_LIMIT,
    VK_TEXT_LIMIT,
    PLATFORMS,
    escapeHtml,
    truncate,
    buildPost,
    buildVkPost,
    buildPostFor,
    platformOf,
    fillPrompt,
  };
}
  return module.exports;
})();

const { DatabaseSync } = require('node:sqlite');
const settings = $('Настройки').first().json;
const minRelevance = Number(settings.MIN_RELEVANCE ?? 6);

const db = new DatabaseSync(settings.CF_DB_PATH);
try {
  const log = logLib.createLog(db, { normalizeUrl: filterLib.normalizeUrl });
  log.init();
  const out = [];
  $input.all().forEach((it, i) => {
    const news = $('Промпт').itemMatching(i).json;
    const content = it.json && it.json.choices && it.json.choices[0] && it.json.choices[0].message
      ? it.json.choices[0].message.content
      : null;
    if (typeof content !== 'string') {
      log.rejected(news.link, 'ошибка запроса к нейросети');
      return;
    }
    const r = parseLib.parseModelResponse(content, { minRelevance });
    if (!r.ok) {
      log.rejected(news.link, r.reason, { relevance: r.relevance });
      return;
    }
    let post;
    try {
      // Запас 64 знака под строку с оценкой в сообщении редактору.
      post = postLib.buildPost(
        { title: news.title, text: r.text, link: news.link, sourceName: news.source },
        { limit: postLib.TELEGRAM_TEXT_LIMIT - 64 }
      );
    } catch (e) {
      log.rejected(news.link, 'пост не собран: ' + e.message, { relevance: r.relevance });
      return;
    }
    log.drafted(news.link, post.text, { relevance: r.relevance });
    out.push({
      json: {
        id: news.id,
        link: news.link,
        relevance: r.relevance,
        text: post.text,
        // Номер повтора отправки редактору, считает узел «Повтор черновика».
        attempt: 0,
        // Редактору видна оценка нейросети, в канал она не попадает.
        editorText: `Оценка нейросети: ${r.relevance}/10${post.truncated ? ', текст обрезан' : ''}\n\n${post.text}`,
      },
    });
  });
  return out;
} finally {
  db.close();
}

// Узел «Повтор черновика»: ошибки узла «Черновик редактору» (выход ошибок).
// 429: черновик уходит в «Паузу» на retry_after секунд и обратно на отправку, до 3 повторов.
// Иначе причина пишется в журнал, запись остаётся collected, сбор идёт дальше.
// src/retry.js (вклеено scripts/build-workflows.js, править в src/)
const retryLib = (() => {
  const module = { exports: {} };
// Повтор отправки в Телеграм при ошибке 429 (Too Many Requests).
// Телеграм отвечает { ok: false, error_code: 429, description: "Too Many Requests: retry after 5",
// parameters: { retry_after: 5 } }. Узел Telegram в n8n отдаёт ошибку по-разному: объектом,
// строкой или только своим текстом без retry_after, поэтому разбор ищет число везде.
'use strict';

const DEFAULTS = {
  maxRetries: 3, // повторов после первой неудачной отправки
  maxWait: 60, // больше ждать нет смысла: запуск сбора раз в 3 часа
  defaultWait: 10, // если retry_after не нашёлся: 10, 20, 30 секунд
};

function textOf(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

// { tooMany, retryAfter, text } из ответа Телеграма или из элемента ошибки узла n8n.
function telegramError(res) {
  const r = res && typeof res === 'object' ? res : { error: res };
  const err = r.error && typeof r.error === 'object' ? r.error : {};
  const all = textOf(r);

  let retryAfter = null;
  for (const v of [r.parameters && r.parameters.retry_after, err.parameters && err.parameters.retry_after]) {
    if (Number.isFinite(Number(v)) && Number(v) >= 0 && v !== null && v !== '') {
      retryAfter = Number(v);
      break;
    }
  }
  if (retryAfter === null) {
    const m = all.match(/retry[ _]after\\?"?\s*[:=]?\s*(\d+)/i);
    if (m) retryAfter = Number(m[1]);
  }

  const code = r.error_code ?? err.error_code ?? err.httpCode ?? err.code ?? r.httpCode;
  const tooMany = String(code) === '429' || /too many requests|\b429\b/i.test(all) || retryAfter !== null;

  const text =
    r.description ||
    err.description ||
    err.message ||
    (typeof r.error === 'string' ? r.error : '') ||
    r.message ||
    (all !== '{}' ? all : '') ||
    'без описания';
  return { tooMany, retryAfter, text: String(text) };
}

// Что делать после неудачной отправки номер attempt (0 для первой).
// { retry: true, wait, attempt } или { retry: false, reason } для журнала.
function planRetry(res, attempt, options = {}) {
  const o = { ...DEFAULTS, ...options };
  const e = telegramError(res);
  const n = Number(attempt);
  if (!e.tooMany) return { retry: false, reason: `черновик не отправлен редактору: ${e.text}` };
  if (!Number.isInteger(n) || n < 0) {
    return { retry: false, reason: 'черновик не отправлен редактору: 429, номер попытки неизвестен' };
  }
  if (n >= o.maxRetries) {
    return { retry: false, reason: `черновик не отправлен редактору: 429 после ${o.maxRetries} повторов` };
  }
  const wait = e.retryAfter !== null ? Math.max(1, e.retryAfter) : o.defaultWait * (n + 1);
  if (wait > o.maxWait) {
    return { retry: false, reason: `черновик не отправлен редактору: 429, ждать ${wait} с` };
  }
  return { retry: true, wait, attempt: n + 1 };
}

// Черновик не дошёл до редактора: причина в журнал (таблица items из log.js) по номеру записи.
// Статус не меняется, запись остаётся collected. Если редактор уже успел решить, журнал не трогается.
// Возвращает true, если запись обновлена.
function markUndelivered(db, id, reason, now = () => new Date().toISOString()) {
  const r = String(reason || '').trim();
  if (!r) throw new Error('нужна причина');
  const res = db
    .prepare("UPDATE items SET reason = ?, updated_at = ? WHERE id = ? AND status = 'collected'")
    .run(r, now(), Number(id));
  return Number(res.changes) > 0;
}

if (typeof module !== 'undefined') {
  module.exports = { DEFAULTS, telegramError, planRetry, markUndelivered };
}
  return module.exports;
})();

const { DatabaseSync } = require('node:sqlite');
const settings = $('Настройки').first().json;

const db = new DatabaseSync(settings.CF_DB_PATH);
try {
  const out = [];
  $input.all().forEach((it, i) => {
    let draft = it.json || {};
    // n8n кладёт в элемент ошибки входные поля; если их нет, черновик берётся по связи элементов.
    // Без номера попытки повтора нет, чтобы не уйти в бесконечный круг.
    if (draft.id === undefined) {
      try {
        draft = { ...$('Разбор и пост').itemMatching(i).json, attempt: undefined };
      } catch {
        return;
      }
    }
    // Только поля ошибки: в тексте новости тоже может встретиться «429».
    const e = {};
    for (const k of ['error', 'error_code', 'description', 'parameters', 'httpCode']) {
      if (it.json && it.json[k] !== undefined) e[k] = it.json[k];
    }
    const plan = retryLib.planRetry(e, draft.attempt);
    if (plan.retry) {
      out.push({
        json: {
          id: draft.id,
          link: draft.link,
          relevance: draft.relevance,
          text: draft.text,
          editorText: draft.editorText,
          attempt: plan.attempt,
          wait: plan.wait,
        },
        pairedItem: { item: i },
      });
      return;
    }
    retryLib.markUndelivered(db, draft.id, plan.reason);
  });
  return out;
} finally {
  db.close();
}
